#include "PresetBank.h"
static juce::ValueTree makeState(float cut,float res,float env,float dec,float acc,float drv,float wave){juce::ValueTree v("TB3030STATE");auto put=[&](const char*id,float x){juce::ValueTree p("PARAM");p.setProperty("id",id,nullptr);p.setProperty("value",x,nullptr);v.appendChild(p,nullptr);};put("cutoff",cut);put("resonance",res);put("envmod",env);put("decay",dec);put("accent",acc);put("drive",drv);put("wave",wave);return v;}
void PresetBank::initialise(){presets.clear();struct X{const char*n;float c,r,e,d,a,x,w;};X x[]={{"Init Acid",.46,.55,.62,.42,.7,.2,0},{"Silver Box",.34,.72,.78,.28,.8,.12,0},{"Rubber Bass",.27,.38,.48,.68,.55,.1,1},{"Squelch",.52,.91,.85,.32,.9,.25,0},{"Dark Slide",.18,.66,.7,.78,.62,.3,1},{"Warehouse",.44,.84,.68,.4,.88,.62,0},{"Soft Round",.22,.28,.36,.75,.42,.05,1},{"Acid Scream",.69,.96,.9,.22,1,.78,0},{"Hollow Square",.39,.74,.72,.55,.76,.35,1},{"Clean Sequence",.5,.43,.58,.46,.65,.02,0},{"Overdrive",.48,.82,.74,.34,.86,.94,0},{"Subtle Pulse",.29,.5,.44,.71,.5,.14,1},{"Liquid",.41,.88,.94,.64,.9,.38,0},{"Short Zap",.58,.8,.9,.08,.95,.42,0},{"Deep Resonance",.14,.93,.61,.82,.68,.22,1},{"Finale",.62,.9,.86,.38,.96,.72,0}};for(auto&a:x)presets.push_back({a.n,makeState(a.c,a.r,a.e,a.d,a.a,a.x,a.w)});}
void PresetBank::store(int i,const juce::String&n,const juce::ValueTree&s){if(!juce::isPositiveAndBelow(i,size()))return;presets[(size_t)i]={n,s.createCopy()};}
juce::StringArray PresetBank::names()const{juce::StringArray a;for(auto&p:presets)a.add(p.name);return a;}
void PresetBank::saveUserBank(const juce::File&f)const{juce::ValueTree b("BANK");for(auto&p:presets){auto v=p.state.createCopy();v.setProperty("name",p.name,nullptr);b.appendChild(v,nullptr);}if(auto x=b.createXml())x->writeTo(f);}
void PresetBank::loadUserBank(const juce::File&f){if(auto x=juce::XmlDocument::parse(f)){auto b=juce::ValueTree::fromXml(*x);if(b.hasType("BANK")){presets.clear();for(auto v:b)presets.push_back({v.getProperty("name","User"),v.createCopy()});}}}
